import requests, json
B = "http://localhost:8800"
s = requests.Session(); s.trust_env = False
ok = True
def check(n, c, x=""):
    global ok; print(("PASS " if c else "FAIL ") + n, x if not c else ""); ok = ok and bool(c)
r = s.post(B + "/api/login", json={"password": "test-pass-123"}); s.headers["Cookie"] = r.headers["Set-Cookie"].split(";")[0]
adm = {"Cookie": s.headers["Cookie"], "X-Owner-Password": "test-pass-123"}
def put(kind, id, content):
    content = dict(content, id=id, kind=kind)
    return requests.put(B + "/api/adventure/content", json={"kind": kind, "id": id, "content": content}, headers=adm).status_code == 200
def turn(text, sid, tid):
    return s.post(B + "/api/adventure/turn", json={"sessionId": sid, "turnId": tid, "inputText": text}).json()
def outs(o): return [w["publicOutcome"] for w in o.get("worldEvents", [])]
# 没有内容包：引擎不介入
s.post(B + "/api/adventure/session", json={"sessionId": "W0", "op": "start"})
o = turn("现在执行", "W0", "w0t1"); check("没有内容包时不产生世界事件", o["gameCommit"] and outs(o) == [], o)
# 占位内容（无剧情）
put("world", "w", {"startSceneId": "s-a"})
put("scene", "s-a", {"choices": ["s-b", "s-c", "x-a"]}); put("scene", "s-b", {"choices": ["s-c"]}); put("scene", "s-c", {"choices": []})
put("npc", "n1", {"initial": {"locationId": "s-a"}})
put("event", "e1", {"trigger": {"type": "action_resolved", "sceneId": "s-a"}, "effects": [{"type": "set_flag", "target": "f1", "value": True}, {"type": "advance_scene", "target": "s-b"}], "publicOutcome": "PLACEHOLDER-ONE", "repeatPolicy": "once_per_world"})
put("event", "e2", {"trigger": {"type": "scene_entered", "sceneId": "s-b"}, "effects": [{"type": "set_flag", "target": "f2", "value": True}], "publicOutcome": "PLACEHOLDER-TWO"})
put("event", "e3", {"trigger": {"type": "action_resolved", "sceneId": "s-b"}, "preconditions": [{"flag": "f2", "equals": True}], "effects": [{"type": "change_npc_relation", "target": "n1", "value": "friendly"}, {"type": "advance_scene", "target": "s-c"}], "publicOutcome": "PLACEHOLDER-THREE"})
put("event", "e4", {"trigger": {"type": "action_resolved", "sceneId": "s-c"}, "effects": [{"type": "set_flag", "target": "g", "value": True}, {"type": "advance_scene", "target": "nowhere"}], "publicOutcome": "SHOULD-NOT-APPEAR", "priority": 5})
put("event", "e5", {"trigger": {"type": "action_resolved", "sceneId": "s-c"}, "preconditions": [{"flag": "g"}], "effects": [], "publicOutcome": "LEAK-FROM-PARTIAL"})
put("event", "e6", {"trigger": {"type": "action_resolved", "sceneId": "s-c"}, "preconditions": [{"npcRelation": {"npc": "n1", "band": "friendly"}}], "effects": [], "publicOutcome": "PLACEHOLDER-SIX"})
put("event", "e7", {"trigger": {"type": "action_resolved", "sceneId": "s-a"}, "preconditions": [{"unknownLeaf": 1}], "effects": [], "publicOutcome": "UNKNOWN-COND"})
put("event", "e8", {"trigger": {"type": "action_resolved", "sceneId": "s-a"}, "effects": [{"type": "teleport_player", "target": "x"}], "publicOutcome": "UNSUPPORTED-EFFECT"})
s.post(B + "/api/adventure/session", json={"sessionId": "W1", "op": "start"})
o1 = turn("现在执行", "W1", "w1t1")
check("事件链：行动 → 切场景 → scene_entered 事件，按序给出公开结果", outs(o1) == ["PLACEHOLDER-ONE", "PLACEHOLDER-TWO"], o1)
txt = json.dumps(o1, ensure_ascii=False)
check("玩家响应不泄露 id/effects/flag", all(k not in txt for k in ["e1", "f1", "s-b", "advance_scene", "set_flag", "effects"]), txt)
o2 = turn("现在执行", "W1", "w1t2"); check("前置条件满足（f2）才触发下一事件，关系变化", outs(o2) == ["PLACEHOLDER-THREE"], o2)
o3 = turn("现在执行", "W1", "w1t3")
check("非法 effect 的事件整条拒绝（无部分应用，依赖它的事件也不触发），未知条件/不支持的 effect 不触发；合法事件触发", outs(o3) == ["PLACEHOLDER-SIX"], o3)
o4 = turn("现在执行", "W1", "w1t4"); check("once_per_world 不重复", outs(o4) == [], o4)
o1b = turn("现在执行", "W1", "w1t1"); check("同 turnId 重放：同样的结果，不重复应用", outs(o1b) == outs(o1) and o1b.get("replay"), o1b)
s.post(B + "/api/adventure/session", json={"sessionId": "W2", "op": "start"})
o = turn("现在执行", "W2", "w2t1"); check("另一个会话有自己的世界状态", outs(o) == ["PLACEHOLDER-ONE", "PLACEHOLDER-TWO"], o)
# ===== 世界引擎 v1.1：转场/对话选择提交、新触发器、物品、NPC 记忆、结局锁、兜底、scene.stateEffects（占位内容）=====
put("scene", "x-a", {"choices": ["x-b", "x-c"]}); put("scene", "x-b", {"choices": ["x-c"], "stateEffects": [{"type": "set_flag", "target": "xs", "value": True}]}); put("scene", "x-c", {"choices": []})
put("npc", "n2", {"initial": {}})
ev = lambda i, **k: put("event", i, k)
ev("xe1", trigger={"type": "scene_entered", "sceneId": "x-a"}, effects=[{"type": "set_flag", "target": "xf1", "value": True}], revealsFacts=["xfact1"], publicOutcome={"text": "PH-X1", "availableOnlyAfter": {"committedEventId": "xe1"}, "authorizedFactIds": ["xfact1"], "allowModelToAddNewFacts": False})
ev("xe2", trigger={"type": "fact_discovered", "factId": "xfact1"}, effects=[{"type": "grant_item", "target": "xitem"}, {"type": "record_npc_memory", "target": "n2", "layer": "heardClaims", "value": "claimA"}], publicOutcome="PH-X2")
ev("xe3", trigger={"type": "world_flag_changed", "flagKey": "xf1"}, effects=[{"type": "set_flag", "target": "xf3", "value": True}], publicOutcome="PH-X3")
ev("xe4", trigger={"type": "dialogue_choice_committed", "choiceId": "c1", "npcId": "n2", "sceneId": "x-a"}, effects=[{"type": "change_npc_relation", "target": "n2", "value": "warm"}], publicOutcome="PH-X4")
ev("xe5", trigger={"type": "scene_entered", "sceneId": "x-b"}, preconditions=[{"hasItem": "xitem"}], effects=[{"type": "remove_item", "target": "xitem"}], publicOutcome="PH-X5")
ev("xe6", trigger={"type": "scene_entered", "sceneId": "x-b"}, preconditions=[{"flag": "xs"}], effects=[], publicOutcome="PH-X6")
ev("xe7", trigger={"type": "scene_entered", "sceneId": "x-c"}, effects=[{"type": "lock_flag", "target": "ending", "value": "A"}], publicOutcome="PH-END-A", priority=5)
ev("xe8", trigger={"type": "scene_entered", "sceneId": "x-c"}, effects=[{"type": "lock_flag", "target": "ending", "value": "B"}], publicOutcome="PH-END-B")
ev("xe12", trigger={"type": "scene_entered", "sceneId": "x-c"}, effects=[{"type": "grant_item", "target": "y1"}, {"type": "remove_item", "target": "notheld"}], publicOutcome="PH-BAD-ATOMIC")
ev("xe13", trigger={"type": "scene_entered", "sceneId": "x-c"}, preconditions=[{"hasItem": "y1"}], effects=[], publicOutcome="PH-LEAK-ITEM")
ev("xe14", trigger={"type": "scene_entered", "sceneId": "x-c"}, preconditions=[{"factKnown": "claimA"}], effects=[], publicOutcome="PH-LEAK-CLAIM")
ev("xe15", trigger={"type": "scene_entered", "sceneId": "x-c"}, preconditions=[{"npcMemory": {"npc": "n2", "layer": "heardClaims", "item": "claimA"}}], effects=[], publicOutcome="PH-HEARD")
ev("cyc0", trigger={"type": "scene_entered", "sceneId": "x-c"}, effects=[{"type": "set_flag", "target": "cy", "value": 1}])
ev("cyc1", trigger={"type": "world_flag_changed", "flagKey": "cy"}, effects=[{"type": "set_flag", "target": "cy2", "value": 1}], publicOutcome="PH-C1", repeatPolicy="per_action")
ev("cyc2", trigger={"type": "world_flag_changed", "flagKey": "cy2"}, effects=[{"type": "set_flag", "target": "cy", "value": 2}], publicOutcome="PH-C2", repeatPolicy="per_action")
ev("xfb", trigger={"type": "action_resolved", "sceneId": "x-b", "fallback": True}, effects=[], publicOutcome="PH-FALLBACK", repeatPolicy="per_action")
ev("xsp", trigger={"type": "action_resolved", "sceneId": "x-b", "actionTemplateId": "plain-action"}, effects=[], publicOutcome="PH-SPECIFIC", repeatPolicy="per_action")
def post(path, body): r = s.post(B + path, json=body); return r.status_code, r.json()
def sess(sid): return s.get(B + "/api/adventure/session", params={"id": sid}).json()
def travel(sid, cid, target, **k): return post("/api/adventure/travel", dict(sessionId=sid, commitId=cid, target=target, **k))
def choice(sid, cid, ch, npc="n2"): return post("/api/adventure/choice", dict(sessionId=sid, commitId=cid, choiceId=ch, npcId=npc))
def wo(b): return [w["publicOutcome"] for w in b.get("worldEvents", [])]
seen = []
s.post(B + "/api/adventure/session", json={"sessionId": "X1", "op": "start"})
c, b = travel("X1", "tr0", "x-b"); check("X0 列出的 choices 之外不能转场（x-b 不在 s-a 的 choices 里）", c == 422, b)
turn("现在去搬箱子", "X1", "x1pre")  # s-a 里的行动触发 e1：自动切到 s-b；从 s-b 去不了 x-a。换一个会话测试 x 路径
s.post(B + "/api/adventure/session", json={"sessionId": "X2", "op": "start"})
c, b = travel("X2", "tr1", "x-a"); seen.append(b)
check("X1 转场提交：scene_entered → 公开结果；revealsFacts→fact_discovered；flag 变化→world_flag_changed，按链序", c == 200 and wo(b) == ["PH-X1", "PH-X3", "PH-X2"] and sess("X2")["worldSeq"] == 1, b)
c, b2 = travel("X2", "tr1", "x-a"); check("X2 同 commitId 重放：同样结果、不重复应用、世界序号不变", b2.get("replay") and wo(b2) == wo(b) and sess("X2")["worldSeq"] == 1, b2)
c, b3 = travel("X2", "tr1", "x-c"); check("X3 同 commitId 不同目标 → 409", c == 409, b3)
c, b3 = travel("X2", "tr9", "s-b"); check("X4 不在 choices 里的目标被拒", c == 422, b3)
c, b3 = travel("X2", "tr8", "x-b", expectedVersion=0); check("X5 过期的世界版本被拒（无部分应用）", c == 409 and sess("X2")["worldSeq"] == 1, b3)
c, b3 = choice("X2", "ch0", "nope"); check("X6 不存在的选择被拒", c == 422, b3)
c, b3 = choice("X2", "ch0", "c1", "other"); check("X7 选择必须匹配 NPC", c == 422, b3)
c, b = choice("X2", "ch1", "c1"); seen.append(b); check("X8 对话选择提交 → 事件触发", c == 200 and wo(b) == ["PH-X4"] and sess("X2")["worldSeq"] == 2, b)
c, b2 = choice("X2", "ch1", "c1"); check("X9 重放不重复应用", b2.get("replay") and wo(b2) == ["PH-X4"] and sess("X2")["worldSeq"] == 2, b2)
c, b2 = choice("X2", "ch2", "c1"); check("X10 换 commitId 再选同一个：once_per_world 不重复应用关系变化", c == 200 and wo(b2) == [], b2)
c, b = travel("X2", "tr2", "x-b", expectedVersion=1); seen.append(b); check("X12 进入 x-b：持有物品条件+remove_item；scene.stateEffects 进入时应用", c == 200 and wo(b) == ["PH-X5", "PH-X6"], b)
o = turn("现在执行", "X2", "x2b"); check("X13 兜底事件：没有具体事件回应的可行行动，世界仍然回应", outs(o) == ["PH-FALLBACK"], o)
o = turn("现在去搬箱子", "X2", "x2c"); check("X14 有具体事件时兜底不触发", outs(o) == ["PH-SPECIFIC"], o)
c, b = travel("X2", "tr3", "x-c"); seen.append(b)
check("X15 结局锁：先到先得，冲突的不同结局被整条拒绝；非法 effect 整条拒绝无部分应用；NPC 转述不变成世界事实；环形 flag 触发有界", c == 200 and wo(b) == ["PH-END-A", "PH-HEARD", "PH-C1", "PH-C2"], b)
txt = json.dumps([o, seen], ensure_ascii=False)
check("X16 玩家响应不含内部 id / effect / 授权元数据", all(k not in txt for k in ["xfact1", "xitem", "claimA", "ending", "availableOnlyAfter", "authorizedFactIds", "lock_flag", "heardClaims", "n2", "xf1"]), txt)
s.post(B + "/api/adventure/session", json={"sessionId": "X3", "op": "start"})
c, b = choice("X3", "chx", "c1"); check("X17 不在对应场景时选择不可用", c == 422, b)
c, b = post("/api/adventure/travel", {"sessionId": "nosuch", "commitId": "z", "target": "x-a"}); check("X18 不存在的会话", c == 404, b)
c, b = post("/api/adventure/travel", {"sessionId": "X3"}); check("X19 坏请求", c == 400, b)
# ===== 结局同意契约 + entryRequirements（占位内容）=====
put("scene", "x-a", {"choices": ["x-b", "x-c", "e-gate", "e-enda", "e-endb"]})
put("scene", "e-gate", {"choices": [], "entryRequirements": [{"flag": "gate_open", "equals": True}]})
put("scene", "e-enda", {"choices": [], "ending": {"id": "END-A", "costNotice": "PH-COST-A"}, "entryRequirements": [{"flag": "gate_open", "equals": True}]})
put("scene", "e-endb", {"choices": [], "ending": {"id": "END-B", "costNotice": "PH-COST-B"}})
put("scene", "e-endbad", {"choices": [], "ending": {"id": "END-BAD"}})
ev("xg", trigger={"type": "dialogue_choice_committed", "choiceId": "c-gate", "npcId": "n2", "sceneId": "x-a"}, effects=[{"type": "set_flag", "target": "gate_open", "value": True}], publicOutcome="PH-GATE")
ev("xadv", trigger={"type": "dialogue_choice_committed", "choiceId": "c-adv", "npcId": "n2", "sceneId": "x-a"}, effects=[{"type": "advance_scene", "target": "e-enda"}], publicOutcome="PH-ADV-MUST-NOT-APPEAR")
ev("xpre", trigger={"type": "dialogue_choice_committed", "choiceId": "c-prelock", "npcId": "n2", "sceneId": "x-a"}, effects=[{"type": "lock_flag", "target": "ending_locked", "value": "END-A"}], publicOutcome="PH-PRELOCK")
ev("xlocka", trigger={"type": "scene_entered", "sceneId": "e-enda"}, effects=[{"type": "lock_flag", "target": "ending_locked", "value": "END-A"}], publicOutcome="PH-LOCK-A")
ev("xlockb", trigger={"type": "scene_entered", "sceneId": "e-endb"}, effects=[{"type": "lock_flag", "target": "ending_locked", "value": "END-B"}], publicOutcome="PH-LOCK-B")
def opts(sid): return len(s.get(B + "/api/adventure/world", params={"id": sid}).json().get("options", []))
def start(sid):
    s.post(B + "/api/adventure/session", json={"sessionId": sid, "op": "start"}); return travel(sid, sid + "-t0", "x-a")
start("E1")
check("E1 entryRequirements 未满足：场景不出现在可前往列表里", opts("E1") == 3, opts("E1"))
c, b = travel("E1", "e1a", "e-gate"); check("E2 entryRequirements 未满足的 travel 被拒（统一 not_available）", c == 422 and b["code"] == "not_available", b)
c, b = choice("E1", "e1c0", "c-adv"); seq = sess("E1")["worldSeq"]
check("E3 事件的 advance_scene 不能进入结局场景（整条事件拒绝，无输出）", c == 200 and wo(b) == [], b)
c, b = travel("E1", "e1b", "e-endb")
check("E4 结局 travel 无确认：不提交，返回无剧透的 costNotice，世界序号与场景不变", c == 422 and b["code"] == "ending_confirmation_required" and b["costNotice"] == "PH-COST-B" and sess("E1")["worldSeq"] == seq + 0 and "END-B" not in json.dumps(b), b)
c, b = travel("E1", "e1c", "e-endb", confirmEnding="true"); check("E5 confirmEnding 必须是布尔 true，字符串不算", c == 422 and b["code"] == "ending_confirmation_required", b)
start("E2")
c, b = travel("E2", "e2a", "e-endb", confirmEnding=True)
check("E6 没有先展示 costNotice 就直接带确认：仍被拒，并返回 costNotice（此次才算展示）", c == 422 and b["code"] == "ending_confirmation_required" and b["costNotice"] == "PH-COST-B", b)
c, b = travel("E2", "e2b", "e-enda", confirmEnding=True)
check("E7 确认必须针对被展示过的同一目标（A 的 gate 未开且没展示过）", c == 422, b)
s0 = sess("E2")["worldSeq"]
c, b = travel("E2", "e2c", "e-endb", confirmEnding=True); seen2 = b
check("E8 展示之后单独确认 → 提交，lock_flag 生效，公开结果只有事件文字", c == 200 and wo(b) == ["PH-LOCK-B"] and sess("E2")["worldSeq"] == s0 + 1, b)
c, b = travel("E2", "e2c", "e-endb", confirmEnding=True); check("E9 同 commitId 重放幂等，世界序号不变", c == 200 and b.get("replay") and wo(b) == ["PH-LOCK-B"] and sess("E2")["worldSeq"] == s0 + 1, b)
c, b = travel("E2", "e2c", "x-b", confirmEnding=True); check("E10 同 commitId 不同目标 → 409", c == 409, b)
c, b = travel("E2", "e2d", "e-enda", confirmEnding=True); check("E11 已进入结局后，再走向任何场景都不可用", c == 422, b)
start("E3")
choice("E3", "e3g", "c-gate"); 
c, b = choice("E3", "e3p", "c-prelock"); check("E12 （占位）预先写入结局锁", c == 200 and wo(b) == ["PH-PRELOCK"], b)
c, b = travel("E3", "e3a", "e-endb"); check("E13 已锁定为另一结局：走向别的结局被拒 409，不展示 costNotice", c == 409 and b["code"] == "ending_locked" and "costNotice" not in b, b)
start("E4")
choice("E4", "e4g", "c-gate")
check("E14 entryRequirements 满足后目标出现在可前往列表里", opts("E4") == 5 - 0, opts("E4"))
c, b = travel("E4", "e4a", "e-enda"); c2, b2 = travel("E4", "e4b", "e-endb", confirmEnding=True)
check("E15 对目标 A 的展示不能用来确认目标 B", c == 422 and c2 == 422 and b2["costNotice"] == "PH-COST-B", [b, b2])
c, b = travel("E4", "e4c", "e-enda", confirmEnding=True); check("E16 满足条件+已展示+单独确认 → 进入", c == 200 and wo(b) == ["PH-LOCK-A"], b)
start("E5")
choice("E5", "e5g", "c-gate")
put("scene", "x-a", {"choices": ["e-endbad"]})
c, b = travel("E5", "e5a", "e-endbad", confirmEnding=True); check("E17 ending 缺 costNotice 的场景一律不可用", c == 422 and b["code"] == "not_available", b)
txt = json.dumps(seen2, ensure_ascii=False)
check("E18 玩家响应不含结局 id / lock_flag / ending_locked", all(k not in txt for k in ["END-B", "ending_locked", "lock_flag", "e-endb"]), txt)

# ---- 章节开场快照（占位）----
def snap(sid): return requests.get(B + "/api/adventure/ending-snapshot", params={"id": sid}, headers=adm).json()
check("S1 终局提交成功后建立了一份快照（E2 → END-B）", snap("E2").get("snapshot", {}).get("snapshots") == 1, snap("E2"))
check("S2 同 commitId 重放后仍只有一份快照", snap("E2")["snapshot"]["snapshots"] == 1)
check("S3 未走到结局的会话（E1）没有快照；被拒绝/未确认的结局（E3、E5）也没有", snap("E1")["snapshot"] is None and snap("E3")["snapshot"] is None and snap("E5")["snapshot"] is None)
st = snap("E4")["snapshot"]
check("S4 另一个会话（E4 → END-A）有独立快照，字段只有计数", st is not None and st["learningRefs"] == 0 and st["openThreads"] == 0, st)
check("S5 玩家会话不能读快照计数（403），响应也不含任何 id", requests.get(B + "/api/adventure/ending-snapshot", params={"id": "E2"}, headers={"Cookie": s.headers["Cookie"]}).status_code == 403 and "END-B" not in json.dumps(snap("E2")))

# ---- 未解线索 openThreads / resolvesThreads（占位内容）----
D = lambda i, a, c: {"id": i, "authorizedAudience": a, "carryover": c}
put("scene", "x-a", {"choices": ["t-a"]})
put("scene", "t-a", {"choices": ["t-b", "t-end"], "openThreads": [D("th1", "player", "eligible")]})
put("scene", "t-b", {"choices": ["t-a", "t-end"], "openThreads": [D("th2", "server_private", "eligible"), D("th3", "player", "local_only")]})
put("scene", "t-end", {"choices": [], "ending": {"id": "END-T", "costNotice": "PH-COST-T"}, "entryRequirements": [{"flag": "tg"}]})
ev("te0", trigger={"type": "scene_entered", "sceneId": "t-a"}, effects=[{"type": "set_flag", "target": "tg", "value": True}])
ev("tlock", trigger={"type": "scene_entered", "sceneId": "t-end"}, effects=[{"type": "lock_flag", "target": "ending_locked", "value": "END-T"}], publicOutcome="PH-LOCK-T")
ev("tev1", trigger={"type": "dialogue_choice_committed", "choiceId": "c-open", "npcId": "n2", "sceneId": "t-a"}, openThreads=[D("th4", "player", "eligible")], publicOutcome="PH-T1")
ev("tev2", trigger={"type": "dialogue_choice_committed", "choiceId": "c-res", "npcId": "n2", "sceneId": "t-a"}, resolvesThreads=["th1"], publicOutcome="PH-T2")
ev("tev3", trigger={"type": "dialogue_choice_committed", "choiceId": "c-bad", "npcId": "n2", "sceneId": "t-a"}, resolvesThreads=["never-opened"], publicOutcome="PH-T-BAD")
ev("tev4", trigger={"type": "dialogue_choice_committed", "choiceId": "c-conf", "npcId": "n2", "sceneId": "t-a"}, openThreads=[D("th1", "server_private", "eligible")], publicOutcome="PH-T-CONF")
